from collections import deque

def numBusesToDestination(routes, S, T):
    if S == T:
        return 0

    # Check if S or T is not reachable by any bus
    reachable_S = any(S in route for route in routes)
    reachable_T = any(T in route for route in routes)
    if not reachable_S or not reachable_T:
        return -1

    # Check if S and T are on the same route
    for route in routes:
        if S in route and T in route:
            return 1

    # Build a mapping from stop to the list of bus routes that serve it
    stop_to_routes = {}
    for route_idx, route in enumerate(routes):
        for stop in route:
            if stop not in stop_to_routes:
                stop_to_routes[stop] = []
            stop_to_routes[stop].append(route_idx)

    # BFS setup: queue holds (current_stop, buses_taken)
    queue = deque()
    visited_stops = set()
    visited_routes = set()

    # Start from S
    queue.append((S, 0))
    visited_stops.add(S)

    while queue:
        current_stop, buses_taken = queue.popleft()

        if current_stop == T:
            return buses_taken + 1

        # Explore all routes that serve current_stop
        for route_idx in stop_to_routes.get(current_stop, []):
            if route_idx in visited_routes:
                continue
            visited_routes.add(route_idx)

            # Explore all stops in this route
            for stop in routes[route_idx]:
                if stop not in visited_stops:
                    visited_stops.add(stop)
                    queue.append((stop, buses_taken + 1))

    return -1
